const raw = $input.first().json || {};
const execObj = raw.execution && typeof raw.execution === 'object' ? raw.execution : {};
const wfObj = raw.workflow && typeof raw.workflow === 'object' ? raw.workflow : {};
const errObj = execObj.error && typeof execObj.error === 'object' ? execObj.error : {};

function scrubSecrets(inputText) {
  return String(inputText || 'Unknown n8n execution error')
    .replace(/Bearer\s+[A-Za-z0-9._\-]{8,}/gi, 'Bearer [REDACTED]')
    .replace(/ldx_pat_[0-9a-f]{8}_[0-9a-f]{32}/gi, '[REDACTED_PAT]')
    .replace(/whsec_[A-Za-z0-9+\/=]{8,}/g, '[REDACTED_WHSEC]')
    .replace(/sk-(?:proj-|live-|test-)?[A-Za-z0-9]{16,}/g, '[REDACTED_KEY]')
    .replace(/ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}/g, '[REDACTED_GH]')
    .replace(/xox[baprs]-[A-Za-z0-9-]{10,}/g, '[REDACTED_SLACK]')
    .slice(0, 1000);
}

const envOrg = String(($env && ($env.DX_DEFAULT_ORG_ID || $env.DX_ORG_ID)) || 'native-ui-lab').trim();
const rawOrg = String(raw.organizationId || envOrg || 'native-ui-lab').trim();
const organizationId = /^[a-zA-Z0-9_-]{1,80}$/.test(rawOrg) ? rawOrg : 'native-ui-lab';

const workflowId = String(wfObj.id || 'unknown-workflow').slice(0, 120);
const workflowName = String(wfObj.name || 'LatticeDX n8n Workflow').slice(0, 200);
const executionId = String(execObj.id || 'unknown-exec').slice(0, 120);
const executionUrl = String(execObj.url || '').slice(0, 300);
const lastNodeExecuted = String(execObj.lastNodeExecuted || 'unknown-node').slice(0, 160);
const errorMessage = scrubSecrets(errObj.message || raw.message || 'Unhandled n8n workflow error');
const errorStack = scrubSecrets(errObj.stack || '').slice(0, 600);
const occurredAt = new Date().toISOString();

const telegramMessage = [
  '🚨 [LatticeDX n8n Error Alert]',
  'Workflow: ' + workflowName,
  'Execution: #' + executionId,
  'Node: ' + lastNodeExecuted,
  'Org: ' + organizationId,
  'Error: ' + errorMessage.slice(0, 300),
].join('\n');

const emailSubject = `[LatticeDX][n8n Error] ${workflowName} (#${executionId})`;
const emailBody = [
  'LatticeDX n8n workflow failure detected.',
  `Workflow: ${workflowName} (${workflowId})`,
  `Execution ID: ${executionId}`,
  executionUrl ? `Execution URL: ${executionUrl}` : null,
  `Last Node Executed: ${lastNodeExecuted}`,
  `Organization: ${organizationId}`,
  `Occurred At: ${occurredAt}`,
  `Error: ${errorMessage}`,
].filter(Boolean).join('\n');

return [{
  json: {
    organizationId,
    workflowId,
    workflowName,
    executionId,
    executionUrl,
    lastNodeExecuted,
    errorMessage,
    occurredAt,
    telegramMessage,
    emailSubject,
    emailBody,
    nocobaseEventPayload: {
      organizationId,
      type: 'automation.n8n_failed',
      source: 'n8n:dxos-enterprise-error-handler',
      subject: `${workflowName}:${executionId}`.slice(0, 120),
      data: {
        workflowId,
        workflowName,
        executionId,
        executionUrl: executionUrl || null,
        lastNodeExecuted,
        errorMessage,
        errorStack: errorStack || null,
        severity: 'critical',
        occurredAt,
      },
    },
  },
}];

const ctx = $('Format Error Incident Payload').first().json || {};
const results = $input.all().map((it) => it.json || {});
const failures = results.filter((r) => Boolean(r.error)).length;
return [{
  json: {
    ok: true,
    handled: true,
    organizationId: ctx.organizationId,
    workflowId: ctx.workflowId,
    executionId: ctx.executionId,
    channelsAttempted: results.length,
    channelsDegraded: failures,
    handledAt: new Date().toISOString(),
  },
}];
